function obtenerPreguntas(area, dificultad) {
    const nivel = window.nivelAcademicoSeleccionado || 'bachilleratoAvanzado';
    return (PREGUNTAS_POR_NIVEL[nivel] && PREGUNTAS_POR_NIVEL[nivel][area] && PREGUNTAS_POR_NIVEL[nivel][area][dificultad]) || [];
}

